'use client';
import {FormEvent,useState} from 'react';
type Row={checksum:string;relative_path:string;item_id:string|null;page_count:number|null;
  state:string;extracted_pages:number;ocr_pending_pages:number;failed_pages:number;index_status:string|null;
  metadata:{candidate_volume?:number;candidate_part?:number;transcript_status?:string;playback_status?:string}};
type Page={page_number:number;status:string;error:string|null;result:{text:string;warning:string;confidence?:number|null;extraction_method?:string}|null};
export default function CorpusStatus({api,canReview=false}:{canReview?:boolean;api:(path:string,options?:RequestInit)=>Promise<Response>}){
  const [reviewId,setReviewId]=useState('');const [reviewBusy,setReviewBusy]=useState(false);
  const [rows,setRows]=useState<Row[]>([]);const [message,setMessage]=useState('');
  const [pages,setPages]=useState<Page[]>([]);const [selected,setSelected]=useState('');const [offset,setOffset]=useState(0);
  async function refresh(){try{setRows(await (await api('staff/corpus')).json());setMessage('Inventory refreshed.');}catch(e){setMessage(e instanceof Error?e.message:'Inventory unavailable');}}
  async function view(id:string,start=0){try{setPages(await (await api(`staff/corpus/${id}/pages?offset=${start}`)).json());setSelected(id);setOffset(start);}catch(e){setMessage(e instanceof Error?e.message:'Pages unavailable');}}
  async function review(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);setReviewBusy(true);try{await api(`staff/corpus/${reviewId}/source-review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_locator:form.get('source'),rights_statement:form.get('rights'),public_display_approved:form.get('public')==='on',volume_number:form.get('volume')?Number(form.get('volume')):null,part_number:form.get('part')?Number(form.get('part')):null,language:form.get('language')})});setReviewId('');await refresh();setMessage('Source review recorded. Content verification and publication remain separate. Refresh staff records to see the change.');}catch(e){setMessage(e instanceof Error?e.message:'Review failed');}finally{setReviewBusy(false);}}
  return <details className="source" onToggle={e=>{if(e.currentTarget.open&&!rows.length)void refresh();}}>
    <summary>Dataset ingestion and page checkpoints</summary>
    <p>Machine extraction remains unverified. Pending source rights prevent publication. Volume numbers below are filename candidates awaiting edition review.</p>
    <button onClick={()=>void refresh()}>Refresh ingestion progress</button><p role="status">{message}</p>
    {rows.map(row=><section className="source" key={row.checksum}><h3>{row.relative_path}</h3>
      <p>{row.state} · {row.page_count?`${row.extracted_pages}/${row.page_count} pages extracted · ${row.ocr_pending_pages} OCR pending · ${row.failed_pages} failed`:'Media/reference item'} · Research index: {row.index_status||'not eligible'}</p>
      {row.metadata.candidate_volume&&<p>Candidate volume {row.metadata.candidate_volume}{row.metadata.candidate_part&&` · Part ${row.metadata.candidate_part}`}</p>}
      {row.metadata.transcript_status&&<p>Transcript: {row.metadata.transcript_status}</p>}
      {row.metadata.playback_status&&<p>{row.metadata.playback_status}</p>}
      {canReview&&row.item_id&&<button onClick={()=>setReviewId(row.item_id!)}>Review source and rights for {row.relative_path}</button>}{row.item_id&&row.page_count&&<button onClick={()=>void view(row.item_id!)}>Inspect extracted pages</button>}
    </section>)}
    {reviewId&&<form onSubmit={review} className="source"><h3>Explicit source and rights review</h3><p>Record independently checked evidence. This action does not publish anything.</p><label>Verified acquisition or source URL<input name="source" type="url" required/></label><label>Evidence and permission statement<textarea name="rights" minLength={10} maxLength={1000} required/></label><label>Verified language<input name="language" required maxLength={80}/></label><label>Verified volume (optional)<input name="volume" type="number" min="1" max="100"/></label><label>Verified part (optional)<input name="part" type="number" min="1"/></label><label><input name="public" type="checkbox"/> The reviewed rights permit public display</label><label><input type="checkbox" required/> I independently checked provenance and the stated permission</label><button disabled={reviewBusy}>Record source review</button><button type="button" onClick={()=>setReviewId('')}>Cancel review</button></form>}
    {selected&&<section aria-label="Checkpoint pages"><h3>Machine-extracted page preview</h3>{pages.map(page=><article key={page.page_number}><h4>Physical page {page.page_number} · {page.status}</h4><p>{page.error||page.result?.warning}</p><p className="subtle">Method: {page.result?.extraction_method||"Not recorded"} · OCR confidence: {page.result?.confidence!=null?`${(page.result.confidence*100).toFixed(1)}% (machine estimate, not verification)`:"Not available"}</p><pre className="original-text whitespace-pre-wrap">{page.result?.text}</pre></article>)}<button disabled={offset===0} onClick={()=>void view(selected,Math.max(0,offset-25))}>Previous 25 pages</button><button disabled={pages.length<25} onClick={()=>void view(selected,offset+25)}>Next 25 pages</button></section>}
  </details>;
}

