'use client';
import { useEffect, useRef, useState } from 'react';
type Cue = {start:number; end:number; text:string};
export default function RecordingReview({id,mime,api,onChanged}:{id:string; mime:string; api:(path:string,options?:RequestInit)=>Promise<Response>; onChanged:()=>Promise<void>}) {
 const [history,setHistory]=useState<{revision:number;status:string}[]>([]);const [current,setCurrent]=useState(0);
 const [technical,setTechnical]=useState<{mime_type:string;byte_size:number;checksum:string;processing_provenance:{duration_seconds?:number;streams?:{codec_name:string;codec_type:string;width?:number;height?:number}[]}}|null>(null);
 const [cues,setCues]=useState<Cue[]>([{start:0,end:1,text:''}]); const [revision,setRevision]=useState(0); const [status,setStatus]=useState(''); const [message,setMessage]=useState(''); const [url,setUrl]=useState(''); const [busy,setBusy]=useState(false); const [checked,setChecked]=useState(false); const opened=useRef(false);const apiRef=useRef(api);useEffect(()=>{apiRef.current=api;},[api]);
 useEffect(()=>()=>{if(opened.current)void apiRef.current(`staff/documents/${id}/playback-stop`,{method:'POST'}).catch(()=>{});},[id]);
 async function run(action:()=>Promise<void>){setBusy(true);try{await action();}catch(e){setMessage(e instanceof Error?e.message:'Request failed');}finally{setBusy(false);}}
 async function closePlayback(){if(opened.current){opened.current=false;setUrl('');await apiRef.current(`staff/documents/${id}/playback-stop`,{method:'POST'});setMessage('Private playback closed. Load the recording to open a new session.');}}
 async function load(){setTechnical(await(await api(`staff/documents/${id}/media-metadata`)).json());const row=await (await api(`staff/documents/${id}/recording`)).json();if(row){setCues(row.transcript);setRevision(row.revision);setStatus(row.status);setHistory(row.revisions||[]);setCurrent(row.current_revision||row.revision);} const playback=await(await api(`staff/documents/${id}/playback-session`,{method:'POST'})).json();setUrl(playback.playback_url);opened.current=true;setMessage('Private playback lasts 30 minutes; reopen if expired. Compare every cue with the original. Filename titles do not establish speaker identity.');}
 async function viewRevision(n:number){const row=await(await api(`staff/documents/${id}/recording?revision=${n}`)).json();setCues(row.transcript);setRevision(row.revision);setCurrent(row.current_revision);setHistory(row.revisions);setStatus(row.status);setChecked(false);}
 async function save(){const row=await(await api(`staff/documents/${id}/recording`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({base_revision:revision,cues})})).json();setRevision(row.revision);setCurrent(row.revision);setHistory(h=>[{revision:row.revision,status:row.status},...h]);setStatus(row.status);setChecked(false);setMessage('New transcript revision saved. Publication has been withdrawn for review.');await onChanged();}
 return <details className="source" onToggle={event=>{if(event.target===event.currentTarget&&!event.currentTarget.open)void run(closePlayback);}}><summary>Review recording and transcript</summary><button disabled={busy} onClick={()=>void run(load)}>Load recording and current transcript</button>{url && (mime.startsWith('video/')?<video controls src={url} aria-label="Original recording" onError={()=>setMessage("Playback expired or unavailable. Load the recording again.")}/>:<audio controls src={url} aria-label="Original recording" onError={()=>setMessage("Playback expired or unavailable. Load the recording again.")}/>)}<details><summary>Technical recording metadata</summary>{technical&&<><p>{technical.mime_type} · {technical.byte_size} bytes · {technical.processing_provenance.duration_seconds ?? "Unknown"} seconds</p><p>SHA-256: {technical.checksum}</p>{technical.processing_provenance.streams?.map((s,i)=><p key={i}>{s.codec_type}: {s.codec_name} {s.width&&`${s.width}×${s.height}`}</p>)}</>}</details><label>Transcript history<select value={revision} disabled={busy||!history.length} onChange={e=>void run(()=>viewRevision(Number(e.target.value)))}>{history.map(h=><option value={h.revision} key={h.revision}>Revision {h.revision} · {h.status}</option>)}</select></label>{revision!==current&&<p>Historical revision; read only. Select the current revision to make corrections.</p>}<p>Revision {revision} · {status || 'No transcript'} · Times in seconds</p>{cues.map((cue,i)=><fieldset key={i} disabled={revision!==current||busy}><legend>Cue {i+1}</legend>{(['start','end'] as const).map(key=><label key={key}>{key}<input type="number" min="0" step="0.1" value={cue[key]} onChange={e=>setCues(cues.map((c,n)=>n===i?{...c,[key]:Number(e.target.value)}:c))}/></label>)}<label>Transcript text<textarea value={cue.text} onChange={e=>setCues(cues.map((c,n)=>n===i?{...c,text:e.target.value}:c))}/></label><button onClick={()=>setCues(cues.filter((_,n)=>n!==i))}>Remove cue {i+1}</button></fieldset>)}<div className="button-row"><button disabled={revision!==current||cues.length>=200} onClick={()=>setCues([...cues,{start:cues.at(-1)?.end||0,end:(cues.at(-1)?.end||0)+1,text:''}])}>Add cue</button><button disabled={revision!==current||busy||!url||!cues.length} onClick={()=>void run(save)}>Save new reviewed revision</button></div><label><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/> I compared the saved revision with the original recording.</label><button disabled={revision!==current||busy||!checked||status!=='reviewed'} onClick={()=>void run(async()=>{await api(`staff/documents/${id}/recording/verify`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,compared_with_recording:true})});setStatus('verified');setMessage('Transcript verified. Publish the record separately.');await onChanged();})}>Verify saved transcript</button><p role="status">{busy?'Working…':message}</p></details>;
}
