'use client';
import { FormEvent, useRef, useState } from 'react';

export default function UploadSteps({onSubmit,busy}:{onSubmit:(event:FormEvent<HTMLFormElement>)=>Promise<void>;busy:boolean}) {
  const [step,setStep]=useState(1); const [fileInfo,setFileInfo]=useState('');
  const form=useRef<HTMLFormElement>(null);
  const input='block w-full rounded border border-slate-300 bg-white p-2 mt-1';
  function next(){
    const fields=form.current?.querySelectorAll<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>(`[data-step="${step}"] input, [data-step="${step}"] select, [data-step="${step}"] textarea`);
    if(fields && [...fields].every(field=>field.reportValidity()))setStep(n=>n+1);
  }
  return <form ref={form} onSubmit={onSubmit} onReset={()=>{setStep(1);setFileInfo('');}} className="mt-4">
    <p role="status">Step {step} of 3 · {['Upload','Basic details','Source and rights'][step-1]}</p>
    <fieldset data-step="1" hidden={step!==1}><legend>1. Choose an original</legend>
      <label>Original file · PDF, image, text, WAV, MP3 or H.264/AAC MP4 · 10 MiB maximum<input name="file" type="file" accept="application/pdf,image/png,image/jpeg,text/plain,audio/wav,audio/mpeg,video/mp4" required className={input} onChange={e=>{const file=e.target.files?.[0];e.target.setCustomValidity(file && file.size>10*1024*1024?'This file exceeds the current 10 MiB limit. Keep the original; do not split or compress it to bypass preservation safeguards.':'');setFileInfo(file?`${file.name} · ${(file.size/1024/1024).toFixed(2)} MiB · ${file.type || 'Type checked by server'}`:'');const type=form.current?.elements.namedItem('material_type') as HTMLSelectElement|null;if(file&&type)type.value=file.type.startsWith('image/')?'photograph':file.type.startsWith('audio/')?'speech':file.type.startsWith('video/')?'video':'document';}} /></label>
      <p>{fileInfo}</p><p className="subtle">PDF processing currently supports up to 50 pages. Large-volume ingestion needs a separately validated workflow.</p>
    </fieldset>
    <fieldset data-step="2" hidden={step!==2}><legend>2. Describe the material</legend>
      {[['title','Title'],['language','Language']].map(([name,label])=><label key={name}>{label}<input name={name} maxLength={200} required className={input}/></label>)}
      <label>Material type<select name="material_type" className={input}><option value="document">Document</option><option value="manuscript">Manuscript / letter</option><option value="photograph">Photograph</option><option value="speech">Speech / audio</option><option value="video">Video</option></select></label>
      <label>Description<textarea name="description" maxLength={2000} className={input}/></label>
    </fieldset>
    <fieldset data-step="3" hidden={step!==3}><legend>3. Record source and rights</legend>
      <p>Use verified source details. Access to a file does not establish permission. Keep uncertain material outside the public archive pending review.</p>
      {[['source_name','Source name'],['source_locator','Verified source URL'],['source_record_locator','Source record URL'],['rights_statement','Rights / permission statement']].map(([name,label])=><label key={name}>{label}<input name={name} type={name.includes('locator')?'url':'text'} maxLength={name==='rights_statement'?1000:200} required className={input}/></label>)}
      <label>Access after publication<select name="access_level" className={input}><option value="staff">Staff only</option><option value="public">Public</option></select></label>
      <label><input type="checkbox" required/> I checked the source locator and permission to preserve this file under the stated rights.</label>
      <p>Preserving the original does not publish it. Next: processing → review and correction → verification → separate publication decision.</p>
    </fieldset>
    <div className="button-row">{step>1&&<button type="button" disabled={busy} onClick={()=>setStep(n=>n-1)}>Back</button>}{step<3?<button type="button" className="button" onClick={next}>Continue</button>:<button className="button" disabled={busy}>{busy?'Preserving original…':'Preserve original'}</button>}</div>
  </form>;
}
